  if(session.role==='Siswa') return [...stored,...(studentRecords[submenu]||[{id:session.personId+'-GEN',title:`${submenu} · ${session.name}`,meta:`${module} · Data personal`,status:'Aktif',detail:`Data ini hanya untuk ${session.name} (${session.personId}). Workspace siswa tidak memuat siswa lain.`}])];
